[CmdletBinding(SupportsShouldProcess)]
param()
$ErrorActionPreference='Stop'
$parseTokens=$null;$parseErrors=$null
$null=[Management.Automation.Language.Parser]::ParseFile($PSCommandPath,[ref]$parseTokens,[ref]$parseErrors)
if ($parseErrors.Count) { throw ($parseErrors | Out-String) }
Import-Module PSScriptAnalyzer -ErrorAction Stop
$analysis=@(Invoke-ScriptAnalyzer -Path $PSCommandPath -Severity Warning,Error -WhatIf:$false)
if ($analysis.Count) { throw ($analysis | Out-String) }
Write-Output 'Parser errors=0; PSScriptAnalyzer warnings/errors=0.'
if (-not $PSCmdlet.ShouldProcess('verdict.md and verdict.json','Serialize the complete independent round 4 verdict inside this receipt')) { return }
$identity=Get-Content -LiteralPath (Join-Path $PSScriptRoot 'reviewer-identity.json') -Raw | ConvertFrom-Json
$request=Get-Content -LiteralPath (Join-Path $PSScriptRoot 'request.jsonl') -Raw | ConvertFrom-Json
$findings=[Collections.Generic.List[object]]::new()
function Add-ReviewFinding {
    param([string]$Id,[string]$Status,[string]$Severity,[int]$Line,[string]$Section,[string]$Evidence,[string]$Rationale,[string]$Correction,[string]$File='docs/plans/PLAN-NATIVERESTORE-001.md')
    $findings.Add([pscustomobject][ordered]@{id=$Id;status=$Status;severity=$Severity;file=$File;line=$Line;section=$Section;evidence=$Evidence;rationale=$Rationale;correction=$Correction})
}
